  [466195] = { "$N2秒ごとに$N1のFireダメージを受けて燃えます。この効果は重なります。", "最大体力の90%を超えて回復するまで、$D1ごとに燃えて$N1のFireダメージを受けます。\n直接の回復でスタックが1つ解除されます。", 0xca3a7fdc, 0x855f3378, "uu" },
  [466211] = { "術者の前方の円錐範囲にいる敵を打ち、吹き飛ばします。", "回復効果が$N1%減少します。$N3秒ごとに$N2のNatureダメージを受けます。", 0x61a1859e, 0x07892c89, "uu" },
  [466219] = { "術者は影に包まれます。呪文、近接攻撃、遠隔攻撃が術者に命中すると、攻撃者は$N1のShadowダメージを受けます。攻撃者がダメージを受けるのは数秒に一度だけです。このダメージは脅威を発生させません。チャージ$N2回。$D1持続します。", "攻撃を受けると、攻撃者に$N1のShadowダメージを与えます。このダメージは脅威を発生させません。残り$N2回。", 0x3a134e5f, 0x49d9a232, "uu" },
