  [466266] = { "術者は影に包まれます。呪文、近接攻撃、遠隔攻撃が術者に命中すると、攻撃者は$N1のShadowダメージを受けます。攻撃者がダメージを受けるのは数秒に一度だけです。このダメージは脅威を発生させません。チャージ$N2回。$D1持続します。", "攻撃を受けると、攻撃者に$N1のShadowダメージを与えます。このダメージは脅威を発生させません。残り$N2回。", 0x3a134e5f, 0x49d9a232, "uu" },
  [466269] = { "術者は影に包まれます。呪文、近接攻撃、遠隔攻撃が術者に命中すると、攻撃者は$N1のShadowダメージを受けます。攻撃者がダメージを受けるのは数秒に一度だけです。このダメージは脅威を発生させません。チャージ$N2回。$D1持続します。", "攻撃を受けると、攻撃者に$N1のShadowダメージを与えます。このダメージは脅威を発生させません。残り$N2回。", 0x3a134e5f, 0x49d9a232, "uu" },
